askDelete(){const u=S.me,g=!!u.google,m=CFG.supportEmail,q=encodeURIComponent(T('Peço a eliminação da minha conta Aquipay ({a}).',{a:u.email||''}));sheet(`<h3 style="margin-bottom:.5rem">Eliminar a minha conta</h3><p class="mut" style="margin-bottom:1rem">Esta ação é definitiva. Apagamos o teu perfil, os teus documentos e os teus anúncios, e terminamos a sessão em todos os dispositivos. Não é possível recuperar a conta.</p><p class="err" id="perr" role="alert"></p>${g?fd('Email da conta','dce','email','','autocomplete="off"'):fd('Palavra-passe atual','dcp','password','','autocomplete="current-password"')}<p class="mut" style="margin:.4rem 0 1rem">${g?'Para confirmar, escreve o email da tua conta.':'Para confirmar, escreve a palavra-passe da tua conta.'}</p><div class="stack"><button class="btn" style="background:var(--bad)" data-a="deleteAccount">Eliminar definitivamente</button><button class="btn secondary" data-a="close">Cancelar</button><a class="link" style="text-align:center" href="mailto:${m}?subject=${encodeURIComponent(T('Eliminação da conta Aquipay'))}&body=${q}">Prefiro pedir por email</a></div>`)},
async deleteAccount(){const u=S.me,g=!!u.google,v=(g?$('dce'):$('dcp')).value,e=$('perr');if(!v)return e.textContent=T('Preenche todos os campos.');if(u.apiToken){try{await api('/api/me',{method:'DELETE',body:JSON.stringify(g?{confirmEmail:v}:{password:v})})}catch(x){return e.textContent=x.message}}else if(g?v.trim().toLowerCase()!==String(u.email||'').toLowerCase():u.pw!==await hash(v,u.id))return e.textContent=T(g?'Confirmação incorreta.':'Palavra-passe atual incorreta.');const id=u.id,mine=S.vagas.filter(x=>x.ownerId===id).map(x=>x.id),gone={users:[id],vagas:mine,cands:S.cands.filter(c=>c.userId===id||c.ownerId===id||mine.includes(c.vagaId)).map(c=>c.id),notifs:S.notifs.filter(n=>n.uid===id).map(n=>n.id),reviews:S.reviews.filter(r=>r.ownerId===id||r.reviewerId===id||r.targetId===id).map(r=>r.id),messages:S.messages.filter(x=>x.from===id||x.to===id).map(x=>x.id)};for(const[st,ids]of Object.entries(gone))for(const x of ids)try{await del(st,x)}catch{}for(const st of Object.keys(gone))S[st]=S[st].filter(r=>!gone[st].includes(r.id));const bl={...(S.st.blocks||{})};delete bl[id];S.st.blocks=bl;await put('kv',S.st);S.me=null;S.v='home';await put('kv',{id:'session',uid:null});closeSheet();render();toast('Conta eliminada.')},
