async changePassword(){const e=$('perr'),cur=$('pwc').value,nw=$('pwn').value,u=S.me;if(!cur||!nw)return e.textContent=T('Preenche todos os campos.');if(nw.length<10)return e.textContent=T('A palavra-passe deve ter pelo menos 10 caracteres.');if(u.apiToken){try{await api('/api/auth/password',{method:'POST',body:JSON.stringify({currentPassword:cur,newPassword:nw})})}catch(x){return e.textContent=x.message}}else if(u.pw!==await hash(cur,u.id))return e.textContent=T('Palavra-passe atual incorreta.');u.pw=await hash(nw,u.id);await saveUser(u);closeSheet();toast('Palavra-passe alterada.')},
forgot(){sheet(`<h3 style="margin-bottom:.5rem">Recuperar palavra-passe</h3><p class="mut" style="margin-bottom:1rem">Indica o email da tua conta e enviamos um link para criares uma nova palavra-passe.</p><p class="err" id="perr" role="alert"></p>${fd('Email','fe','email','','autocomplete="email"')}<div class="stack" style="margin-top:.8rem"><button class="btn" data-a="sendForgot">Enviar link</button><button class="btn secondary" data-a="close">Cancelar</button></div>`);const le=$('le');if(le&&le.value)$('fe').value=le.value},
async sendForgot(){const e=$('fe').value.trim().toLowerCase(),r=$('perr');if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(e))return r.textContent=T('Indica um email válido.');try{await api('/api/auth/forgot',{method:'POST',body:JSON.stringify({email:e,lang:LANG})});sheet(`<h3 style="margin-bottom:.5rem">Recuperar palavra-passe</h3><p class="mut" style="margin-bottom:1rem">Se existir uma conta com este email, enviámos um link para criar uma nova palavra-passe. Confere também a pasta de spam.</p><button class="btn" data-a="close">Concluir</button>`)}catch(x){r.textContent=x.message}},
async doReset(){const a=$('rp').value,b=$('rp2').value,r=$('err');if(a.length<10)return r.textContent=T('A palavra-passe deve ter pelo menos 10 caracteres.');if(a!==b)return r.textContent=T('As palavras-passe não coincidem.');try{await api('/api/auth/reset',{method:'POST',body:JSON.stringify({token:S.resetToken,password:a})});S.resetToken=null;S.v='home';render();toast('Palavra-passe alterada. Já podes entrar.')}catch(x){r.innerHTML=esc(x.message)+' <a class="link" data-a="forgotFromReset">Pedir novo link</a>'}},
forgotFromReset(){S.v='home';render();A.forgot()},
report(el){if(!S.me?.apiToken)return toast('Inicia sessão com ligação à internet para denunciar.');const d=el.dataset;sheet(`<h3 style="margin-bottom:.8rem">${d.t==='listing'?'Denunciar anúncio':'Denunciar perfil'}</h3><div class="fd"><label for="rrs">Motivo</label><select id="rrs">${[['spam','Spam ou publicidade'],['fraud','Fraude ou burla'],['abuse','Assédio ou conteúdo ofensivo'],['illegal','Conteúdo ilegal'],['fake','Perfil ou anúncio falso'],['other','Outro motivo']].map(([k,l])=>`<option value="${k}">${l}</option>`).join('')}</select></div><div class="fd"><label for="rdt">Detalhes (opcional)</label><textarea id="rdt" maxlength="800"></textarea></div><div class="stack"><button class="btn" data-a="sendReport" data-t="${esc(d.t)}" data-id="${esc(d.id||'')}" data-cid="${esc(d.cid||'')}">Enviar denúncia</button><button class="btn secondary" data-a="close">Cancelar</button></div>`)},
async sendReport(el){const d=el.dataset;let tid=d.cid||'';if(d.t==='listing')tid=(S.vagas.find(x=>x.id===d.id)||{}).cloudListingId||'';else if(!tid)tid=(U(d.id)||{}).cloudId||'';if(!tid)return toast('Não foi possível enviar a denúncia. Tenta novamente.');try{await api('/api/reports',{method:'POST',body:JSON.stringify({targetType:d.t,targetId:tid,reason:$('rrs').value,details:$('rdt').value.trim()})});closeSheet();toast('Denúncia enviada. Obrigado por ajudar a manter o Aquipay seguro.')}catch(e){toast(e.message)}},
blockUser(el){const d=el.dataset,u=d.id?U(d.id):null,name=u?u.nome:(d.name||T('Utilizador'));sheet(`<h3 style="margin-bottom:.5rem">${T('Bloquear {a}?',{a:esc(name)})}</h3><p class="mut" style="margin-bottom:1rem">Deixarás de ver os anúncios e o perfil desta pessoa, e ela não poderá enviar-te propostas.</p><div class="stack"><button class="btn" data-a="doBlock" data-id="${esc(d.id||'')}" data-cid="${esc(d.cid||'')}" data-name="${esc(name)}">Bloquear</button><button class="btn secondary" data-a="close">Cancelar</button></div>`)},
async doBlock(el){const d=el.dataset,u=d.id?U(d.id):null,cid=d.cid||(u&&u.cloudId)||'',id=u?u.id:cid;if(!id)return closeSheet();const l=myBlocks().filter(b=>b.id!==id);l.push({id,cloudId:cid||null,name:d.name||(u&&u.nome)||''});await saveBlocks(l);if(cid&&S.me.apiToken){try{await api('/api/blocks',{method:'POST',body:JSON.stringify({userId:cid})})}catch{}}closeSheet();render();toast('Utilizador bloqueado.')},
blockedList(){const l=myBlocks();sheet(`<h3 style="margin-bottom:.8rem">Utilizadores bloqueados</h3>${l.length?l.map(b=>`<div class="card ho"><div style="flex:1"><b>${esc(b.name||T('Utilizador'))}</b></div><button class="btn secondary" style="width:auto" data-a="unblock" data-id="${esc(b.id)}">Desbloquear</button></div>`).join(''):'<p class="mut">Não bloqueaste ninguém.</p>'}`)},
