(async()=>{render();try{const[us,vs,cs,ns,rs,ms,kv]=await Promise.all(['users','vagas','cands','notifs','reviews','messages','kv'].map(s=>tx(s,'readonly',o=>o.getAll())));Object.assign(S,{users:us,vagas:vs,cands:cs,notifs:ns,reviews:rs,messages:ms});const st=kv.find(x=>x.id==='settings');if(st)Object.assign(S.st,st);const ss=kv.find(x=>x.id==='session');S.me=ss&&ss.uid?U(ss.uid)||null:null}catch{}const rt=new URLSearchParams(location.search).get('reset');if(rt){S.resetToken=rt;S.v='reset';history.replaceState(null,'','/')}const slug=location.pathname.replace(/^\/+|\/+$/g,'');if(typeof DOCS!=='undefined'&&DOCS[slug]){S.v='doc';S.doc=slug}const token=new URLSearchParams(location.search).get('share');if(token){S.shared=decodeShare(token);if(!S.shared)S.shared={type:'invalid'};const rb=document.createElement('meta');rb.name='robots';rb.content='noindex,nofollow';document.head.appendChild(rb);if(S.shared.title||S.shared.name)document.title=(S.shared.title||S.shared.name)+' · Aquipay'}theme();S.ready=true;render();if(S.me?.apiToken){syncPush();syncBlocks()}})();
